"use client";

import { useState } from "react";
import { brandOf } from "@/features/flights/airline-brands";
import {
  WORLD_MAP_PATH,
  WORLD_MAP_VIEW_BOX,
} from "@/features/flights/components/world-map";
import {
  airlineLogoUrl,
  seatPositionOf,
  summarizeBoardingPass,
} from "@/features/flights/flight-schema";
import { cn } from "@/lib/utils";
import type { AirlineBrand } from "@/features/flights/airline-brands";
import type { BoardingPassData } from "@/features/flights/flight-schema";
import type { CSSProperties, ReactNode } from "react";

export type BoardingPassCardState = "streaming" | "loading" | "ready" | "error";

/**
"map" draws the world map behind the ticket on the theme's card color. "brand" paints the whole ticket in the airline's color with no map, and falls back to "map" for an airline with no color in AIRLINE_BRANDS.
*/
export type BoardingPassVariant = "map" | "brand";

export interface BoardingPassCardProperties {
  readonly state: BoardingPassCardState;
  /**
  The flight number from the props, shown before the pass arrives.
  */
  readonly flight?: string;
  readonly data?: BoardingPassData;
  readonly error?: string;
  /**
  @default "map"
  */
  readonly variant?: BoardingPassVariant;
  readonly className?: string;
}

/**
The ticket's outline: a 1px ring in the theme's border color, drawn with drop-shadow so it follows the notches the mask cuts. A brand ticket sets --ticket-edge to its own color, since the color already marks the edge.
*/
const TICKET_OUTLINE =
  "[filter:drop-shadow(1px_0_0_var(--ticket-edge,var(--border)))_drop-shadow(-1px_0_0_var(--ticket-edge,var(--border)))_drop-shadow(0_1px_0_var(--ticket-edge,var(--border)))_drop-shadow(0_-1px_0_var(--ticket-edge,var(--border)))]";

const BRAND_TEXT = { dark: "#111111", light: "#FFFFFF" } as const;

/**
A brand ticket re-points the theme's tokens at the airline's color, so every bg-card, text-muted-foreground and border-border inside it follows without a second set of classes.
*/
function brandStyle({ color, text }: AirlineBrand): CSSProperties {
  const ink = BRAND_TEXT[text];
  return {
    "--background": color,
    "--border": `color-mix(in oklab, ${ink} 30%, transparent)`,
    "--card": color,
    "--card-foreground": ink,
    "--foreground": ink,
    "--muted": `color-mix(in oklab, ${ink} 18%, transparent)`,
    "--muted-foreground": `color-mix(in oklab, ${ink} 72%, transparent)`,
    "--ticket-edge": color,
  } as CSSProperties;
}

/**
Two half-circle notches where the stub tears off, 7rem from the right edge (the stub's width), cut only when the ticket is wide enough to have a stub.
*/
const TICKET_NOTCHES =
  "@xl:[mask:radial-gradient(circle_9px_at_calc(100%_-_7rem)_0,#0000_97%,#000)_top/100%_51%_no-repeat,radial-gradient(circle_9px_at_calc(100%_-_7rem)_100%,#0000_97%,#000)_bottom/100%_51%_no-repeat]";

const TICKET =
  "bg-card text-card-foreground relative isolate flex overflow-hidden rounded-2xl";

const LABEL =
  "text-muted-foreground text-[10px] leading-4 font-medium tracking-[0.08em] uppercase";

const BIG = "text-2xl leading-8 font-bold tabular-nums";

const SMALL = "text-muted-foreground text-xs leading-4";

const POSITION_TITLES = {
  aisle: "Aisle",
  middle: "Middle",
  window: "Window",
} as const;

const LONG_DATE = new Intl.DateTimeFormat("en-US", {
  day: "numeric",
  month: "short",
  timeZone: "UTC",
  weekday: "short",
  year: "numeric",
});

const WHITESPACE = /\s+/u;

/**
"2026-11-03" reads "Tue, Nov 3, 2026".
*/
function longDate(date: string) {
  const parsed = new Date(`${date}T00:00:00Z`);
  return Number.isNaN(parsed.getTime()) ? date : LONG_DATE.format(parsed);
}

/**
"Jon Doe" reads "DOE/JON", the way a pass prints a name.
*/
function passName(passenger: string) {
  const parts = passenger.trim().split(WHITESPACE);
  const last = parts.pop() ?? "";
  return (parts.length > 0 ? `${last}/${parts.join(" ")}` : last).toUpperCase();
}

const WorldMap = () => (
  <svg
    viewBox={WORLD_MAP_VIEW_BOX}
    preserveAspectRatio="xMidYMid slice"
    aria-hidden
    className="text-foreground/[0.06] pointer-events-none absolute inset-0 -z-10 size-full"
  >
    <path d={WORLD_MAP_PATH} fill="currentColor" />
  </svg>
);

const Bar = ({ className }: { readonly className?: string }) => (
  <span
    aria-hidden
    className={cn("bg-muted block animate-pulse rounded", className)}
  />
);

const LOGO_TILE = "size-8 shrink-0 rounded-lg";

const AirlineLogo = ({
  airlineCode,
  isOnBrand = false,
}: {
  readonly airlineCode: string;
  /**
  On a brand ticket the logo sits on a white tile, so a logo in the airline's own color stays visible.
  */
  readonly isOnBrand?: boolean;
}) => {
  const [failed, setFailed] = useState(false);
  if (failed) {
    return (
      <span
        aria-hidden
        className={cn(
          LOGO_TILE,
          "bg-muted text-muted-foreground flex items-center justify-center font-mono text-xs uppercase"
        )}
      >
        {airlineCode}
      </span>
    );
  }
  return (
    // eslint-disable-next-line @next/next/no-img-element, react-doctor/nextjs-no-img-element, jsx-a11y/no-noninteractive-element-interactions -- next/image would force the logo host into the installer's next.config; onError swaps in the letter tile, it is not a user interaction
    <img
      src={airlineLogoUrl(airlineCode)}
      alt=""
      width={32}
      height={32}
      loading="lazy"
      onError={() => setFailed(true)}
      className={cn(
        LOGO_TILE,
        isOnBrand
          ? "bg-white object-contain p-0.5"
          : "object-cover outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10"
      )}
    />
  );
};

/**
The ticket frame: the main part with the world map behind it (or the airline's color, with a brand), and from @xl a perforation and the stub on the right.
*/
const Ticket = ({
  label,
  stub,
  brand = null,
  className,
  children,
}: {
  readonly label?: string;
  readonly stub: ReactNode;
  readonly brand?: AirlineBrand | null;
  readonly className?: string;
  readonly children: ReactNode;
}) => (
  <article
    aria-label={label}
    style={brand ? brandStyle(brand) : undefined}
    className={cn("@container w-full max-w-2xl", className)}
  >
    <div className={TICKET_OUTLINE}>
      <div className={cn(TICKET, TICKET_NOTCHES)}>
        <div className="relative isolate min-w-0 flex-1 p-4">
          {brand ? null : <WorldMap />}
          {children}
        </div>
        <div
          aria-hidden
          className="border-border my-3 hidden border-l border-dashed @xl:block"
        />
        <div
          aria-hidden
          className="hidden w-28 shrink-0 flex-col items-center justify-between gap-3 p-4 @xl:flex"
        >
          {stub}
        </div>
      </div>
    </div>
  </article>
);

const NO_NOTES: readonly string[] = [];

const Column = ({
  label,
  value,
  notes = NO_NOTES,
  className,
}: {
  readonly label: string;
  readonly value: string;
  readonly notes?: readonly string[];
  readonly className?: string;
}) => (
  <div className={cn("flex min-w-0 flex-col", className)}>
    <dt className={LABEL}>{label}</dt>
    <dd className={cn(BIG, "truncate")}>{value}</dd>
    {notes.map((note) => (
      <dd key={note} className={cn(SMALL, "truncate")}>
        {note}
      </dd>
    ))}
  </div>
);

const GroupBox = ({ group = "–" }: { readonly group?: string }) => (
  <div className="border-foreground flex size-20 flex-col items-center justify-center rounded-md border-2 text-center">
    <span className={cn(LABEL, "text-foreground leading-3")}>
      Boarding
      <br />
      group
    </span>
    <span className="text-3xl leading-9 font-bold tabular-nums">{group}</span>
  </div>
);

const COLUMNS =
  "grid grid-cols-2 gap-x-4 gap-y-3 @xl:grid-cols-[1.3fr_1fr_1.2fr_1fr]";

function seatNotes({ seat, cabin }: BoardingPassData) {
  const position = seatPositionOf(seat);
  return position ? [POSITION_TITLES[position], cabin] : [cabin];
}

/**
The line under the name: the booking reference and the extras, when the pass has them.
*/
function detailsOf({ reference, perks = [] }: BoardingPassData) {
  const details = reference ? [`Booking ${reference}`, ...perks] : perks;
  return details.join(", ");
}

const BoardingPassReady = ({
  data,
  variant,
  className,
}: {
  readonly data: BoardingPassData;
  readonly variant: BoardingPassVariant;
  readonly className?: string;
}) => {
  const perks = data.perks ?? [];
  const details = detailsOf(data);
  const brand = variant === "brand" ? brandOf(data.airlineCode) : null;
  return (
    <Ticket
      label={summarizeBoardingPass(data)}
      brand={brand}
      className={className}
      stub={
        <>
          <div className="flex w-full flex-col items-end text-right">
            <span className="font-mono text-xs leading-4 font-semibold">
              {data.reference ?? data.flight}
            </span>
            <span className={SMALL}>
              {data.reference ? data.flight : `Seat ${data.seat}`}
            </span>
          </div>
          <GroupBox group={data.group} />
        </>
      }
    >
      <div aria-hidden className="flex flex-col gap-3">
        <header className="flex items-center justify-between gap-3">
          <div className="flex min-w-0 items-center gap-2.5">
            <AirlineLogo
              key={data.airlineCode}
              airlineCode={data.airlineCode}
              isOnBrand={brand !== null}
            />
            <span className="truncate text-base leading-6 font-bold tracking-[0.06em] uppercase @xl:text-lg @xl:tracking-[0.12em]">
              {data.airline}
            </span>
          </div>
          <div className="flex shrink-0 items-center gap-2">
            {perks.length > 0 ? (
              <span className="hidden text-sm leading-5 @xl:inline">
                {perks[0]}
              </span>
            ) : null}
            <span className="bg-foreground text-background rounded px-2 text-xs leading-5 font-bold uppercase">
              {data.cabin}
            </span>
          </div>
        </header>
        <div>
          <p className="truncate text-base leading-6 font-bold">
            {passName(data.passenger)}
          </p>
          {details ? <p className={cn(SMALL, "truncate")}>{details}</p> : null}
        </div>
        <p className="border-border truncate border-b pb-1.5 text-sm leading-5 font-semibold">
          {data.from.city} to {data.to.city}
        </p>
        <dl className={COLUMNS}>
          <Column
            label={data.flight}
            value={`${data.from.code}–${data.to.code}`}
            notes={[longDate(data.date)]}
          />
          <Column
            label="Gate"
            value={data.gate}
            notes={[
              data.terminal ? `Terminal ${data.terminal}` : "Gate may change",
            ]}
          />
          <Column
            label="Boarding begins"
            value={data.boardingTime}
            notes={
              data.departureTime ? [`Flight departs ${data.departureTime}`] : []
            }
          />
          <Column label="Seat" value={data.seat} notes={seatNotes(data)} />
          <Column
            label="Group"
            value={data.group ?? "–"}
            className="@xl:hidden"
          />
        </dl>
      </div>
    </Ticket>
  );
};

const SkeletonColumn = ({ label }: { readonly label: string }) => (
  <span className="flex flex-col">
    <span className={LABEL}>{label}</span>
    <span className="flex h-8 items-center">
      <Bar className="h-5 w-16" />
    </span>
    <span className="flex h-4 items-center">
      <Bar className="h-2.5 w-20" />
    </span>
  </span>
);

/**
The pass while its data is on the way: the same ticket and rows as the ready pass, so nothing moves when it lands. The flight number shows as soon as the model has written it (with "…" while it's still writing).
*/
export const BoardingPassCardSkeleton = ({
  flight,
  streaming = false,
  className,
}: {
  readonly flight?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <Ticket
    className={className}
    stub={
      <>
        <span className="flex h-8 w-full justify-end">
          <Bar className="h-3 w-12" />
        </span>
        <span className="border-muted size-20 animate-pulse rounded-md border-2" />
      </>
    }
  >
    <output className="flex flex-col gap-3">
      <span className="sr-only">
        {flight
          ? `Loading the boarding pass for ${flight}`
          : "Loading a boarding pass"}
      </span>
      <span aria-hidden className="flex h-8 items-center justify-between">
        <span className="flex items-center gap-2.5">
          <Bar className={LOGO_TILE} />
          <Bar className="h-4 w-32" />
        </span>
        {flight ? (
          <span className="font-mono text-sm uppercase tabular-nums">
            {flight}
            {streaming ? (
              <span className="text-muted-foreground">…</span>
            ) : null}
          </span>
        ) : (
          <Bar className="h-4 w-14" />
        )}
      </span>
      <span aria-hidden className="flex h-6 items-center">
        <Bar className="h-4 w-36" />
      </span>
      <span aria-hidden className="border-border flex h-7 border-b">
        <Bar className="mt-0.5 h-3.5 w-40" />
      </span>
      <span aria-hidden className={COLUMNS}>
        <SkeletonColumn label="Flight" />
        <SkeletonColumn label="Gate" />
        <SkeletonColumn label="Boarding begins" />
        <SkeletonColumn label="Seat" />
      </span>
    </output>
  </Ticket>
);

const BoardingPassError = ({
  flight,
  message = "The flight service didn't respond. Try again in a moment.",
  className,
}: {
  readonly flight?: string;
  readonly message?: string;
  readonly className?: string;
}) => (
  <div
    role="alert"
    className={cn(
      "bg-card text-card-foreground flex w-full max-w-2xl flex-col gap-1 rounded-2xl border p-4",
      className
    )}
  >
    <p className="text-sm font-semibold">
      {flight
        ? `Couldn't load the boarding pass for ${flight.toUpperCase()}`
        : "Couldn't load the boarding pass"}
    </p>
    <p className="text-muted-foreground text-xs">{message}</p>
  </div>
);

/**
A boarding pass shaped like a ticket, over a world map or in the airline's color (variant): the airline, passenger and route, then the flight, gate, boarding time and seat in columns, with the boarding group on a stub that tears off along a perforation. Narrower than @xl, the stub folds away and the group joins the columns.
*/
export const BoardingPassCard = ({
  state,
  flight,
  data,
  error,
  variant = "map",
  className,
}: BoardingPassCardProperties) => {
  if (state === "ready" && data) {
    return (
      <BoardingPassReady data={data} variant={variant} className={className} />
    );
  }
  if (state === "error") {
    return (
      <BoardingPassError
        flight={flight}
        message={error}
        className={className}
      />
    );
  }
  return (
    <BoardingPassCardSkeleton
      flight={flight}
      streaming={state === "streaming"}
      className={className}
    />
  );
};

"use client";

import { useEffect, useState } from "react";
import { BoardingPassCard } from "@/features/flights/components/boarding-pass-card";
import { loadBoardingPass } from "@/features/flights/flight-requests";
import { errorMessage } from "@/features/flights/flight-schema";
import type { BoardingPassVariant } from "@/features/flights/components/boarding-pass-card";
import type { BoardingPassData } from "@/features/flights/flight-schema";

type Load =
  | { status: "loading" }
  | { status: "ready"; data: BoardingPassData }
  | { status: "error"; message: string };

export function LiveBoardingPassCard({
  flight,
  date,
  streaming = false,
  variant = "map",
  className,
}: {
  readonly flight?: string;
  /**
  YYYY-MM-DD. Null or left out: today.
  */
  readonly date?: string | null;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  /**
  "map" (the default) or "brand", the airline's color. See BoardingPassCard.
  */
  readonly variant?: BoardingPassVariant;
  readonly className?: string;
}) {
  const [load, setLoad] = useState<Load>({ status: "loading" });

  useEffect(() => {
    if (streaming || !flight) {
      return;
    }
    let isCancelled = false;
    setLoad({ status: "loading" });
    const run = async () => {
      try {
        const data = await loadBoardingPass(flight, date);
        if (!isCancelled) {
          setLoad({ data, status: "ready" });
        }
      } catch (error) {
        if (!isCancelled) {
          setLoad({
            message: errorMessage(error, "Flight lookup failed."),
            status: "error",
          });
        }
      }
    };
    run();
    return () => {
      isCancelled = true;
    };
  }, [flight, date, streaming]);

  if (streaming || !flight) {
    return (
      <BoardingPassCard
        state="streaming"
        flight={flight}
        className={className}
      />
    );
  }
  if (load.status === "ready") {
    return (
      <BoardingPassCard
        state="ready"
        data={load.data}
        variant={variant}
        className={className}
      />
    );
  }
  if (load.status === "error") {
    return (
      <BoardingPassCard
        state="error"
        flight={flight}
        error={load.message}
        className={className}
      />
    );
  }
  return (
    <BoardingPassCard state="loading" flight={flight} className={className} />
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { AskUserQuestions } from "@/components/ui/ask-user-questions";
import { ChatMessage } from "@/components/ui/chat-message";
import { ThinkingIndicator } from "@/components/ui/thinking-indicator";
import { BoardingPassCard } from "@/features/flights/components/boarding-pass-card";
import DatePicker from "@/features/flights/components/date-picker";
import FlightResults from "@/features/flights/components/flight-results";
import RoutePicker from "@/features/flights/components/route-picker";
import SeatMapPicker from "@/features/flights/components/seat-map";
import { runCheckInConversation } from "@/features/flights/check-in-conversation";
import { spring } from "@/lib/springs";
import { cn } from "@/lib/utils";
import type {
  Answers,
  ConversationEntry,
  ConversationPrompt,
} from "@/features/flights/check-in-conversation";

/**
Runs the conversation and keeps what it has said so far. Unmounting aborts the run, so its waits and questions never land in a later one.
*/
function useConversation() {
  const [entries, setEntries] = useState<ConversationEntry[]>([]);
  const [prompt, setPrompt] = useState<ConversationPrompt | null>(null);
  const [isThinking, setIsThinking] = useState(false);

  useEffect(() => {
    const controller = new AbortController();
    const view = {
      add: (entry: ConversationEntry) =>
        setEntries((previous) => [...previous, entry]),
      clear: () => setEntries([]),
      prompt: setPrompt,
      think: setIsThinking,
    };
    runCheckInConversation(view, controller.signal);
    return () => controller.abort();
  }, []);

  const answer = (answers: Answers) => {
    setPrompt(null);
    prompt?.resolve(answers);
  };

  return { answer, entries, isThinking, prompt };
}

/**
Keeps the newest message in view as the conversation grows.
*/
function useFollow() {
  const scrollReference = useRef<HTMLDivElement>(null);
  const contentReference = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const element = scrollReference.current;
    const content = contentReference.current;
    if (!element || !content) {
      return;
    }
    const observer = new ResizeObserver(() => {
      element.scrollTo({ behavior: "smooth", top: element.scrollHeight });
    });
    observer.observe(content);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return { contentReference, scrollReference };
}

const ENTER = {
  animate: { opacity: 1, y: 0 },
  initial: { opacity: 0, y: 6 },
  transition: spring.slow,
} as const;

function EntryView({ entry }: { readonly entry: ConversationEntry }) {
  if (entry.kind === "route") {
    return (
      <motion.div {...ENTER}>
        <RoutePicker onConfirm={(route) => entry.resolve(route)} />
      </motion.div>
    );
  }
  if (entry.kind === "date") {
    return (
      <motion.div {...ENTER}>
        <DatePicker
          defaultDate={entry.defaultDate}
          onConfirm={(date) => entry.resolve(date)}
        />
      </motion.div>
    );
  }
  if (entry.kind === "flights") {
    return (
      <motion.div {...ENTER}>
        <FlightResults
          offers={entry.offers}
          onConfirm={(flight) => entry.resolve(flight)}
        />
      </motion.div>
    );
  }
  if (entry.kind === "seats") {
    return (
      <motion.div {...ENTER}>
        <SeatMapPicker
          map={entry.data.seatMap}
          flight={entry.data.pass.flight}
          defaultSeat={entry.defaultSeat}
          onConfirm={(seat) => entry.resolve(seat)}
        />
      </motion.div>
    );
  }
  if (entry.kind === "pass") {
    return (
      <motion.div {...ENTER}>
        <BoardingPassCard state="ready" data={entry.data} variant="brand" />
      </motion.div>
    );
  }
  return <ChatMessage from={entry.kind}>{entry.text}</ChatMessage>;
}

/**
An airline check-in assistant with no message box: it asks pre-built questions with Fluid Functionalism's AskUserQuestions where the composer would be (a task to tap, a route card with searchable cities, a booking form whose answers are checked as they're submitted, then baggage, a seat map to pick a seat from, and extras) and ends with the boarding pass in the airline's colors, the way the airline would issue it. The conversation is a script (features/flights/check-in-conversation.ts), so it needs no model.
*/
export default function CheckInAgent({
  className,
}: {
  readonly className?: string;
}) {
  const { answer, entries, isThinking, prompt } = useConversation();
  const { contentReference, scrollReference } = useFollow();

  return (
    <div className={cn("flex min-h-0 flex-col", className)}>
      <div
        ref={scrollReference}
        className="flex min-h-0 flex-1 flex-col overflow-y-auto p-4"
      >
        <div ref={contentReference} className="flex flex-col gap-4">
          {entries.map((entry) => (
            <EntryView key={entry.id} entry={entry} />
          ))}
          {isThinking ? <ThinkingIndicator className="px-0" /> : null}
        </div>
      </div>
      <AnimatePresence mode="popLayout">
        {prompt ? (
          <motion.div
            key={prompt.id}
            className="p-3 pt-0"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, transition: spring.moderate.exit }}
            transition={spring.moderate}
          >
            <AskUserQuestions
              questions={prompt.questions}
              defaultAnswers={prompt.defaultAnswers}
              onComplete={answer}
            />
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useId, useState } from "react";
import { ChevronDown, ChevronUp, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { formatPrice } from "@/features/flights/check-in-questions";
import { seatOptionOf } from "@/features/flights/flight-schema";
import { cn } from "@/lib/utils";
import type {
  SeatMap,
  SeatMapSeat,
  SeatOption,
} from "@/features/flights/flight-schema";
import type { CSSProperties } from "react";

const AISLE = "0.5rem";
const ROW_LABEL = "1.5rem";
const SEAT_SIZE = "1.75rem";

const POSITION_TITLES = {
  aisle: "Aisle",
  middle: "Middle",
  window: "Window",
} as const;

type SeatState = "taken" | "picked" | "booked" | "legroom" | "free";

/**
How each seat looks: taken seats are darker and crossed out, the pick is filled in, the booked seat is outlined, and the legroom row has a dashed edge.
*/
const SEAT_STATES: Record<SeatState, string> = {
  booked: "bg-foreground/10 border-primary/60 border-2",
  free: "bg-foreground/10 peer-hover:bg-foreground/20",
  legroom:
    "bg-foreground/10 peer-hover:bg-foreground/20 border-foreground/40 border border-dashed",
  picked: "bg-primary text-primary-foreground",
  taken: "bg-foreground/30 text-foreground/60",
};

/**
The grid's columns: the row number, then each block's seats with an aisle between blocks.
*/
function gridOf(blocks: readonly string[][]): CSSProperties {
  const columns = blocks.flatMap((block, index) => [
    ...(index > 0 ? [AISLE] : []),
    ...block.map(() => SEAT_SIZE),
  ]);
  return { gridTemplateColumns: [ROW_LABEL, ...columns].join(" ") };
}

/**
"Aisle, $14" for a seat to switch to, "Window, your seat now" for the booked one.
*/
function describe(option: SeatOption) {
  const parts: string[] = [POSITION_TITLES[option.position]];
  if (option.legroom) {
    parts.push("extra legroom");
  }
  parts.push(option.current ? "your seat now" : formatPrice(option.price));
  return parts.join(", ");
}

function stateOf(
  seat: SeatMapSeat,
  picked: string,
  map: SeatMap,
  isLegroom: boolean
): SeatState {
  if (seat.taken) {
    return "taken";
  }
  if (seat.seat === picked) {
    return "picked";
  }
  if (seat.seat === map.current) {
    return "booked";
  }
  return isLegroom ? "legroom" : "free";
}

/**
One seat: a radio input under a square, so the browser's arrow keys move through the free seats.
*/
function Seat({
  name,
  seat,
  state,
  label,
  isLocked,
  onPick,
}: {
  readonly name: string;
  readonly seat: string;
  readonly state: SeatState;
  readonly label: string;
  readonly isLocked: boolean;
  readonly onPick: (seat: string) => void;
}) {
  const isTaken = state === "taken";
  return (
    <label
      className={cn(
        "relative block size-7",
        isTaken || isLocked ? "cursor-not-allowed" : "cursor-pointer"
      )}
    >
      <input
        type="radio"
        name={name}
        value={seat}
        aria-label={label}
        checked={state === "picked"}
        disabled={isTaken || isLocked}
        onChange={() => onPick(seat)}
        className="peer sr-only"
      />
      <span
        aria-hidden
        className={cn(
          "flex size-7 items-center justify-center rounded-md text-[10px] leading-none font-semibold tabular-nums transition-colors",
          "peer-focus-visible:ring-ring peer-focus-visible:ring-2 peer-focus-visible:ring-offset-1",
          SEAT_STATES[state],
          isLocked && state !== "picked" && !isTaken && "opacity-60"
        )}
      >
        {isTaken ? <X className="size-3.5" /> : null}
        {state === "picked" ? seat : null}
      </span>
    </label>
  );
}

const Legend = () => (
  <ul className="text-muted-foreground flex flex-wrap justify-center gap-x-3 gap-y-1 text-xs leading-4">
    <li className="flex items-center gap-1.5">
      <span className="bg-foreground/10 size-3 rounded-sm" /> Available
    </li>
    <li className="flex items-center gap-1.5">
      <span className="bg-foreground/10 border-foreground/40 size-3 rounded-sm border border-dashed" />{" "}
      Extra legroom
    </li>
    <li className="flex items-center gap-1.5">
      <span className="bg-foreground/30 size-3 rounded-sm" /> Taken
    </li>
    <li className="flex items-center gap-1.5">
      <span className="bg-primary size-3 rounded-sm" /> Yours
    </li>
  </ul>
);

/**
A seat map for picking a seat in a chat: the cabin front to back in a plane's outline, column letters across the top and row numbers down the side, taken seats crossed out and the pick filled in with its seat number. "Confirm" calls onConfirm once and locks the map with the pick showing.
*/
export default function SeatMapPicker({
  map,
  flight,
  defaultSeat,
  onConfirm,
  className,
}: {
  readonly map: SeatMap;
  /**
  e.g. "BA 117", for the map's label.
  */
  readonly flight: string;
  /**
  The seat picked when the map opens; the booked seat when left out.
  */
  readonly defaultSeat?: string;
  readonly onConfirm?: (seat: string) => void;
  readonly className?: string;
}) {
  const name = useId();
  const [picked, setPicked] = useState(defaultSeat ?? map.current);
  const [isLocked, setIsLocked] = useState(false);
  const option = seatOptionOf(map, picked);
  const letters = map.blocks.flat();
  const blockEnds = new Set(
    map.blocks.slice(0, -1).map((block) => block.at(-1))
  );

  return (
    <section
      aria-label={`Seat map for ${flight}`}
      className={cn(
        "bg-card text-card-foreground flex w-full max-w-sm flex-col items-center gap-3 rounded-t-[7rem] rounded-b-[2rem] border px-4 pt-7 pb-4",
        className
      )}
    >
      <p className="text-muted-foreground flex flex-col items-center text-xs leading-4">
        <ChevronUp aria-hidden className="size-4" />
        Front of plane
      </p>
      <fieldset disabled={isLocked} className="min-w-0">
        <legend className="sr-only">Seats</legend>
        <div className="grid items-center gap-1" style={gridOf(map.blocks)}>
          <span />
          {letters.map((letter) => [
            <span
              key={letter}
              aria-hidden
              className="text-muted-foreground text-center text-xs leading-6"
            >
              {letter}
            </span>,
            blockEnds.has(letter) ? <span key={`${letter}-aisle`} /> : null,
          ])}
          {map.rows.map((row) => [
            <span
              key={row.row}
              aria-hidden
              className="text-muted-foreground text-xs tabular-nums"
            >
              {row.row}
            </span>,
            ...row.seats.map((seat, index) => {
              const state = stateOf(seat, picked, map, row.legroom);
              const seatOption = seatOptionOf(map, seat.seat);
              const details = seatOption ? `, ${describe(seatOption)}` : "";
              const label = seat.taken
                ? `Seat ${seat.seat}, taken`
                : `Seat ${seat.seat}${details}`;
              return [
                <Seat
                  key={seat.seat}
                  name={name}
                  seat={seat.seat}
                  state={state}
                  label={label}
                  isLocked={isLocked}
                  onPick={setPicked}
                />,
                blockEnds.has(letters[index]) ? (
                  <span key={`${seat.seat}-aisle`} />
                ) : null,
              ];
            }),
          ])}
        </div>
      </fieldset>
      <p className="text-muted-foreground flex flex-col items-center text-xs leading-4">
        Back of plane
        <ChevronDown aria-hidden className="size-4" />
      </p>
      <Legend />
      <div className="border-border flex w-full items-center justify-between gap-3 border-t pt-3">
        <p aria-live="polite" className="min-w-0 text-sm leading-5">
          <span className="font-semibold">Seat {picked}</span>
          {option ? (
            <span className="text-muted-foreground block truncate text-xs leading-4">
              {describe(option)}
            </span>
          ) : null}
        </p>
        {isLocked ? (
          <span className="text-muted-foreground shrink-0 text-xs">
            Confirmed
          </span>
        ) : (
          <Button
            onClick={() => {
              setIsLocked(true);
              onConfirm?.(picked);
            }}
          >
            {picked === map.current ? "Keep seat" : "Confirm seat"}
          </Button>
        )}
      </div>
    </section>
  );
}

"use client";

import { useId, useState } from "react";
import { ArrowUpDown, PlaneLanding, PlaneTakeoff } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
} from "@/components/ui/combobox";
import {
  CITIES,
  destinationsFrom,
  findCity,
} from "@/features/flights/flight-network";
import { fontWeights } from "@/lib/font-weight";
import { useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import { cn } from "@/lib/utils";
import type { NetworkCity } from "@/features/flights/flight-network";

export interface Route {
  from: string;
  to: string;
}

interface CityItem {
  value: string;
  label: string;
}

const itemOf = (city: NetworkCity): CityItem => ({
  label: city.city,
  value: city.city,
});

/**
Only cities with a flight out of them can be a starting point.
*/
const ORIGINS = CITIES.flatMap((city) =>
  destinationsFrom(city).length > 0 ? [itemOf(city)] : []
);

/**
A city matches its name, any alias, or any airport code, so "nyc", "jfk", and "new" all find New York.
*/
function matches(item: CityItem, query: string) {
  const typed = query.trim().toLowerCase();
  const city = findCity(item.value);
  if (!typed || !city) {
    return true;
  }
  const isNamed = city.city.toLowerCase().includes(typed);
  const isAliased = city.aliases.some((alias) => alias.startsWith(typed));
  return (
    isNamed ||
    isAliased ||
    city.codes.some((code) => code.toLowerCase().startsWith(typed))
  );
}

/**
Whether the demo has a flight from the first city to the second.
*/
function hasFlight(start: string, end: string) {
  const city = findCity(start);
  return city
    ? destinationsFrom(city).some((entry) => entry.city === end)
    : false;
}

/**
One searchable city field: a caption label over a Fluid Combobox whose rows show the city and its airport codes.
*/
function CityField({
  label,
  icon,
  items,
  value,
  placeholder,
  isDisabled,
  onChange,
}: {
  readonly label: string;
  readonly icon: typeof PlaneTakeoff;
  readonly items: readonly CityItem[];
  readonly value: string;
  readonly placeholder: string;
  readonly isDisabled: boolean;
  readonly onChange: (city: string) => void;
}) {
  const id = useId();
  const sizes = useSize();
  return (
    <div className="flex min-w-0 flex-col gap-1">
      <label
        htmlFor={id}
        className={cn(sizes.type.caption, "text-muted-foreground")}
      >
        {label}
      </label>
      <Combobox
        items={items}
        value={value}
        onValueChange={onChange}
        filter={matches}
        disabled={isDisabled}
      >
        <ComboboxInput id={id} icon={icon} placeholder={placeholder} />
        <ComboboxContent>
          <ComboboxEmpty>No flights to that city in this demo.</ComboboxEmpty>
          <ComboboxList>
            {(item) => {
              const city = findCity(
                typeof item === "string" ? item : item.value
              );
              return city ? (
                <ComboboxItem key={city.city} value={city.city}>
                  {city.city}{" "}
                  <span className="text-muted-foreground">
                    {city.codes.join(", ")}
                  </span>
                </ComboboxItem>
              ) : null;
            }}
          </ComboboxList>
        </ComboboxContent>
      </Combobox>
    </div>
  );
}

/**
A card for picking a route in a chat, the way the calendar picks a date: two Fluid Combobox fields that search cities by name or airport code, a swap button, and a confirm button. To only lists cities with a flight from the picked From city, so every route it offers exists. The confirm button calls onConfirm once and locks the card with the route showing.
*/
export default function RoutePicker({
  confirmLabel = "Pick a date",
  onConfirm,
  className,
}: {
  readonly confirmLabel?: string;
  readonly onConfirm?: (route: Route) => void;
  readonly className?: string;
}) {
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [isLocked, setIsLocked] = useState(false);
  const sizes = useSize();
  const shape = useShape();

  const fromCity = findCity(from);
  const destinations = fromCity ? destinationsFrom(fromCity).map(itemOf) : [];
  const canSwap = Boolean(from && to) && hasFlight(to, from) && !isLocked;
  const isReady = Boolean(from && to);
  const iconSize = sizes.variant === "compact" ? "icon-compact" : "icon";

  const pickFrom = (city: string) => {
    setFrom(city);
    if (!hasFlight(city, to)) {
      setTo("");
    }
  };

  return (
    <section
      aria-label="Route"
      className={cn(
        "bg-card text-card-foreground flex w-full max-w-sm flex-col gap-2 border p-3",
        shape.container,
        className
      )}
    >
      <div className="flex items-center gap-2">
        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <CityField
            label="From"
            icon={PlaneTakeoff}
            items={ORIGINS}
            value={from}
            placeholder="City or airport"
            isDisabled={isLocked}
            onChange={pickFrom}
          />
          <CityField
            label="To"
            icon={PlaneLanding}
            items={destinations}
            value={to}
            placeholder={fromCity ? "City or airport" : "Pick From first"}
            isDisabled={isLocked || !fromCity}
            onChange={setTo}
          />
        </div>
        <Button
          variant="ghost"
          size={iconSize}
          aria-label="Swap From and To"
          disabled={!canSwap}
          onClick={() => {
            setFrom(to);
            setTo(from);
          }}
        >
          <ArrowUpDown />
        </Button>
      </div>
      <div className="border-border flex items-center justify-between gap-3 border-t pt-3">
        <p
          aria-live="polite"
          className={cn(
            sizes.type.body,
            "min-w-0 truncate",
            isReady ? "text-foreground" : "text-muted-foreground"
          )}
          style={{
            fontVariationSettings: isReady
              ? fontWeights.semibold
              : fontWeights.normal,
          }}
        >
          {isReady ? `${from} to ${to}` : "Pick both cities"}
        </p>
        {isLocked ? (
          <span
            className={cn(sizes.type.caption, "text-muted-foreground shrink-0")}
          >
            Picked
          </span>
        ) : (
          <Button
            disabled={!isReady}
            onClick={() => {
              setIsLocked(true);
              onConfirm?.({ from, to });
            }}
          >
            {confirmLabel}
          </Button>
        )}
      </div>
    </section>
  );
}

"use client";

import { useId, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { FluidHoverHighlight } from "@/components/fluid-hover-highlight";
import { Button } from "@/components/ui/button";
import { localToday } from "@/features/flights/flight-schema";
import {
  useFluidHover,
  useRegisterFluidHoverItem,
} from "@/hooks/use-fluid-hover";
import { fontWeights } from "@/lib/font-weight";
import { useIcons } from "@/lib/icon-context";
import { useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import { spring } from "@/lib/springs";
import { cn } from "@/lib/utils";

const MS_PER_DAY = 86_400_000;
const MONTH_FORMAT = new Intl.DateTimeFormat("en-US", {
  month: "long",
  timeZone: "UTC",
  year: "numeric",
});
const DAY_FORMAT = new Intl.DateTimeFormat("en-US", {
  day: "numeric",
  month: "long",
  timeZone: "UTC",
  weekday: "long",
});
const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"] as const;
/**
The selection pill's fade, the same 80ms the library's highlights use.
*/
const FADE = { duration: 0.08 } as const;

/**
The first of a month as YYYY-MM-01, from any date in it.
*/
function monthOf(date: string) {
  return `${date.slice(0, 7)}-01`;
}

function addMonths(month: string, count: number) {
  const date = new Date(`${month}T00:00:00Z`);
  date.setUTCMonth(date.getUTCMonth() + count);
  return date.toISOString().slice(0, 10);
}

function addDays(date: string, count: number) {
  const day = new Date(`${date}T00:00:00Z`);
  day.setUTCDate(day.getUTCDate() + count);
  return day.toISOString().slice(0, 10);
}

/**
The month's days as YYYY-MM-DD, and how many blank cells go before the 1st so it lands on its weekday.
*/
function daysOf(month: string) {
  const first = new Date(`${month}T00:00:00Z`);
  const next = new Date(`${addMonths(month, 1)}T00:00:00Z`);
  const count = Math.round((next.getTime() - first.getTime()) / MS_PER_DAY);
  return {
    days: Array.from({ length: count }, (_, index) => addDays(month, index)),
    lead: first.getUTCDay(),
  };
}

function readable(date: string) {
  return DAY_FORMAT.format(new Date(`${date}T00:00:00Z`));
}

/**
One day: a radio under a square cell the size of the month buttons (36px, 28px compact). The cell has no hover or fill of its own; the grid's fluid hover highlight and the selection pill sit under it. The number turns semibold when picked over the label's 80ms, inside a fixed-size cell, so nothing reflows.
*/
function Day({
  name,
  date,
  index,
  isPicked,
  isOff,
  isToday,
  registerItem,
  onPick,
}: {
  readonly name: string;
  readonly date: string;
  readonly index: number;
  readonly isPicked: boolean;
  readonly isOff: boolean;
  readonly isToday: boolean;
  readonly registerItem: (index: number, element: HTMLElement | null) => void;
  readonly onPick: (date: string) => void;
}) {
  const reference = useRef<HTMLLabelElement>(null);
  const sizes = useSize();
  const shape = useShape();
  useRegisterFluidHoverItem(registerItem, index, reference);
  return (
    <label
      ref={reference}
      data-off={isOff || undefined}
      className={cn(
        "relative z-10 block justify-self-center",
        isOff ? "cursor-not-allowed" : "cursor-pointer"
      )}
    >
      <input
        type="radio"
        name={name}
        value={date}
        aria-label={isToday ? `${readable(date)}, today` : readable(date)}
        checked={isPicked}
        disabled={isOff}
        onChange={() => onPick(date)}
        className="peer sr-only"
      />
      <span
        aria-hidden
        className={cn(
          "relative flex items-center justify-center tabular-nums transition-[color,font-variation-settings] duration-80",
          "peer-focus-visible:ring-ring peer-focus-visible:ring-2",
          sizes.variant === "compact" ? "size-7" : "size-9",
          sizes.text,
          shape.bg,
          isOff ? "text-muted-foreground opacity-50" : "text-foreground"
        )}
        style={{
          fontVariationSettings: isPicked
            ? fontWeights.semibold
            : fontWeights.normal,
        }}
      >
        {Number(date.slice(8))}
        {isToday ? (
          <span className="bg-foreground absolute bottom-1 size-1 rounded-full" />
        ) : null}
      </span>
    </label>
  );
}

/**
A calendar for picking a departure date in a chat, built on the same foundations as the library's lists and tabs: square days the size of the month buttons (36px, 28px compact), one fluid hover highlight that glides across the grid, and the pick on a bg-active pill that springs from day to day. Days before today and past the last bookable day are off. The confirm button calls onConfirm once and locks the calendar with the pick showing.
*/
export default function DatePicker({
  defaultDate,
  maxDays = 330,
  confirmLabel = "Search flights",
  onConfirm,
  className,
}: {
  /**
  The day picked when the calendar opens, as YYYY-MM-DD; tomorrow when left out.
  */
  readonly defaultDate?: string;
  /**
  How many days ahead can be picked.
  */
  readonly maxDays?: number;
  readonly confirmLabel?: string;
  readonly onConfirm?: (date: string) => void;
  readonly className?: string;
}) {
  const name = useId();
  const today = localToday();
  const lastDay = addDays(today, maxDays);
  const [picked, setPicked] = useState(defaultDate ?? addDays(today, 1));
  const [month, setMonth] = useState(() => monthOf(picked));
  const [isLocked, setIsLocked] = useState(false);
  const sizes = useSize();
  const shape = useShape();
  const Chevron = useIcons()["chevron-right"];
  const gridReference = useRef<HTMLDivElement>(null);
  const hover = useFluidHover(gridReference, {
    axis: "xy",
    isItemDisabled: (element) => element.dataset.off === "true",
  });

  const { days, lead } = daysOf(month);
  const pickedIndex = days.indexOf(picked);
  const pickedRect =
    pickedIndex === -1 || !hover.isMeasured
      ? null
      : hover.itemRects[pickedIndex];
  const canGoBack = month > monthOf(today);
  const canGoOn = addMonths(month, 1) <= lastDay;
  const iconSize = sizes.variant === "compact" ? "icon-compact" : "icon";

  return (
    <section
      aria-label="Departure date"
      className={cn(
        "bg-card text-card-foreground flex w-full max-w-sm flex-col gap-2 border p-3",
        shape.container,
        className
      )}
    >
      <header className="flex items-center justify-between">
        <Button
          variant="ghost"
          size={iconSize}
          aria-label="Previous month"
          disabled={!canGoBack || isLocked}
          onClick={() => setMonth(addMonths(month, -1))}
        >
          <Chevron className="rotate-180" />
        </Button>
        <h3
          aria-live="polite"
          className={sizes.type.subtitle}
          style={{ fontVariationSettings: fontWeights.semibold }}
        >
          {MONTH_FORMAT.format(new Date(`${month}T00:00:00Z`))}
        </h3>
        <Button
          variant="ghost"
          size={iconSize}
          aria-label="Next month"
          disabled={!canGoOn || isLocked}
          onClick={() => setMonth(addMonths(month, 1))}
        >
          <Chevron />
        </Button>
      </header>
      <div aria-hidden className="grid grid-cols-7">
        {WEEKDAYS.map((weekday) => (
          <span
            key={weekday}
            className={cn(
              sizes.type.caption,
              "text-muted-foreground text-center"
            )}
          >
            {weekday}
          </span>
        ))}
      </div>
      <fieldset disabled={isLocked} className="min-w-0">
        <legend className="sr-only">Day</legend>
        <div
          ref={gridReference}
          {...hover.handlers}
          className="relative grid grid-cols-7"
        >
          <FluidHoverHighlight
            hover={hover}
            hidden={isLocked}
            className={shape.bg}
          />
          <AnimatePresence initial={false}>
            {pickedRect ? (
              <motion.div
                key={month}
                aria-hidden
                className={cn(
                  "bg-active pointer-events-none absolute top-0 left-0",
                  shape.bg
                )}
                // Every day cell is the same size, so only the position moves.
                style={{ height: pickedRect.height, width: pickedRect.width }}
                initial={{ opacity: 0, x: pickedRect.left, y: pickedRect.top }}
                animate={{ opacity: 1, x: pickedRect.left, y: pickedRect.top }}
                exit={{ opacity: 0, transition: FADE }}
                transition={{ ...spring.moderate, opacity: FADE }}
              />
            ) : null}
          </AnimatePresence>
          {lead > 0 ? (
            <span aria-hidden style={{ gridColumn: `span ${lead}` }} />
          ) : null}
          {days.map((date, index) => (
            <Day
              key={date}
              name={name}
              date={date}
              index={index}
              isPicked={date === picked}
              isOff={date < today || date > lastDay}
              isToday={date === today}
              registerItem={hover.registerItem}
              onPick={setPicked}
            />
          ))}
        </div>
      </fieldset>
      <div className="border-border flex items-center justify-between gap-3 border-t pt-3">
        <p
          aria-live="polite"
          className={cn(sizes.type.body, "min-w-0 truncate")}
          style={{ fontVariationSettings: fontWeights.semibold }}
        >
          {readable(picked)}
        </p>
        {isLocked ? (
          <span
            className={cn(sizes.type.caption, "text-muted-foreground shrink-0")}
          >
