*/
export type CheckInStep = "baggage" | "cabin-bag" | "extras";

export const BAGGAGE_STEPS: readonly CheckInStep[] = ["baggage", "cabin-bag"];

export const EXTRAS_STEPS: readonly CheckInStep[] = ["extras"];

