/**
The city a traveler typed, by name, alias or airport code, ignoring case. Null when the demo doesn't fly there.
*/
export function findCity(input: string): NetworkCity | null {
  const typed = input.trim().toLowerCase();
  return (
    CITIES.find(
      (entry) =>
        entry.city.toLowerCase() === typed ||
        entry.aliases.includes(typed) ||
        entry.codes.some((code) => code.toLowerCase() === typed)
    ) ?? null
  );
}

function cityOfCode(code: string) {
  return CITIES.find((entry) => entry.codes.includes(code));
}

/**
The flights from one city to another, any airport in each.
*/
export function flightsBetween(from: NetworkCity, to: NetworkCity) {
  return TIMETABLE.filter(
    (entry) => from.codes.includes(entry.from) && to.codes.includes(entry.to)
  );
}

/**
The cities with a flight from this one, in name order.
*/
export function destinationsFrom(from: NetworkCity): NetworkCity[] {
  const cities = new Set(
    TIMETABLE.filter((entry) => from.codes.includes(entry.from)).map(
      (entry) => cityOfCode(entry.to)?.city
    )
  );
  return CITIES.filter((entry) => cities.has(entry.city));
}

/**
The time zone of an airport the demo flies to; UTC for one it doesn't.
*/
export function zoneOf(code: string) {
  return cityOfCode(code)?.zone ?? "UTC";
}

import "server-only";
import { getBooking } from "@/features/flights/flight-booking";
import { flightsBetween, zoneOf } from "@/features/flights/flight-network";
import { getRoute } from "@/features/flights/flight-route";
import type { NetworkCity } from "@/features/flights/flight-network";
import type { FlightOffer } from "@/features/flights/flight-schema";

const MINUTES_PER_DAY = 1440;
const MINUTES_PER_HOUR = 60;
const HASH_BASE = 31;
const MODULUS = 2_147_483_647;
/**
The share of days each flight operates, so some days on thin routes have none.
*/
const OPERATING_SHARE = 0.85;
const BASE_FARE = 120;
const FARE_PER_MINUTE = 0.55;
const FARE_SPREAD = 0.3;
const CABIN_FARES: Record<string, number> = {
  Business: 4,
  Economy: 1,
  First: 7,
  Premium: 1.8,
};

/**
A stable number from 0 to 1 for a flight on a date.
*/
function chance(seed: string) {
  let state = 1;
  for (const char of seed) {
    state = (state * HASH_BASE + (char.codePointAt(0) ?? 0)) % MODULUS;
  }
  return state / MODULUS;
}

function minutesOf(time: string) {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * MINUTES_PER_HOUR + minutes;
}

const MS_PER_MINUTE = 60_000;
const MS_PER_DAY = MINUTES_PER_DAY * MS_PER_MINUTE;

/**
How far a time zone is ahead of UTC at an instant, in minutes.
*/
function offsetOf(zone: string, instant: number) {
  const format = new Intl.DateTimeFormat("en-US", {
    day: "numeric",
    hour: "numeric",
    hourCycle: "h23",
    minute: "numeric",
    month: "numeric",
    timeZone: zone,
    year: "numeric",
  });
  const parts = format.formatToParts(new Date(instant));
  const part = (type: Intl.DateTimeFormatPartTypes) =>
    Number(parts.find((entry) => entry.type === type)?.value ?? 0);
  const local = Date.UTC(
    part("year"),
    part("month") - 1,
    part("day"),
    part("hour"),
    part("minute")
  );
  return (local - instant) / MS_PER_MINUTE;
}

/**
The local arrival: leave at a local time in one zone, fly for some minutes, land in another zone. Returns the clock time there and how many days after the departure date that is.
*/
function arrivalOf(
  date: string,
  departure: string,
  minutes: number,
  fromZone: string,
  toZone: string
) {
  const dayStart = Date.parse(`${date}T00:00:00Z`);
  const asUtc = dayStart + minutesOf(departure) * MS_PER_MINUTE;
  const leaves = asUtc - offsetOf(fromZone, asUtc) * MS_PER_MINUTE;
  const lands = leaves + minutes * MS_PER_MINUTE;
  const landsLocal = lands + offsetOf(toZone, lands) * MS_PER_MINUTE;
  const landing = new Date(landsLocal);
  const clock = landing.toISOString().slice(11, 16);
  return {
    days: Math.floor((landsLocal - dayStart) / MS_PER_DAY),
    time: clock,
  };
}

/**
The flights from one city to another on a date, earliest first. Routes and airlines are real (adsbdb); the departure time, cabin and fare come from the demo booking, and the arrival is the flight time later in the destination's time zone. Replace this with a flight search API for real schedules and fares.
*/
export async function searchFlights(
  from: NetworkCity,
  to: NetworkCity,
  date: string
): Promise<FlightOffer[]> {
  const operating = flightsBetween(from, to).filter(
    (entry) => chance(`${entry.flight}:${date}:operates`) < OPERATING_SHARE
  );
  const offers = await Promise.all(
    operating.map(async (entry) => {
      const [route, booking] = await Promise.all([
        getRoute(entry.flight),
        getBooking(entry.flight, date),
      ]);
      const arrival = arrivalOf(
        date,
        booking.departureTime,
        entry.minutes,
        zoneOf(entry.from),
        zoneOf(entry.to)
      );
      const spread =
        1 + (chance(`${entry.flight}:${date}:fare`) - 0.5) * FARE_SPREAD;
      const fare =
        (BASE_FARE + entry.minutes * FARE_PER_MINUTE) *
        (CABIN_FARES[booking.cabin] ?? 1) *
        spread;
      return {
        ...route,
        arrivalDays: arrival.days,
        arrivalTime: arrival.time,
        cabin: booking.cabin,
        date,
        departureTime: booking.departureTime,
        flight: entry.flight,
        minutes: entry.minutes,
        price: Math.round(fare),
      };
    })
  );
  return offers.toSorted((a, b) =>
    a.departureTime.localeCompare(b.departureTime)
  );
}

import "server-only";
import type { FlightPlace } from "@/features/flights/flight-schema";

interface AdsbdbAirport {
  iata_code: string;
  municipality: string;
  name: string;
}

interface AdsbdbRoute {
  response:
    | string
    | {
        flightroute: {
          airline: { name: string; iata: string | null } | null;
          origin: AdsbdbAirport;
          destination: AdsbdbAirport;
        };
      };
}

/**
How long to wait for adsbdb before the route answers with an error instead of hanging.
*/
const ROUTE_TIMEOUT_MS = 8000;

export class FlightNotFoundError extends Error {
  constructor(flight: string, options?: ErrorOptions) {
    super(`Couldn't find flight ${flight}.`, options);
    this.name = "FlightNotFoundError";
  }
}

function placeOf(airport: AdsbdbAirport): FlightPlace {
  return {
    airport: airport.name,
    city: airport.municipality,
    code: airport.iata_code,
  };
}

export async function getRoute(flight: string) {
  const callsign = flight.replaceAll(" ", "");
  const response = await fetch(
    `https://api.adsbdb.com/v0/callsign/${encodeURIComponent(callsign)}`,
    { signal: AbortSignal.timeout(ROUTE_TIMEOUT_MS) }
  );
  if (response.status === 404 || response.status === 400) {
    throw new FlightNotFoundError(flight);
  }
  if (!response.ok) {
    throw new Error(`The flight route service returned ${response.status}.`);
  }
  const body = (await response.json()) as AdsbdbRoute;
  if (typeof body.response === "string") {
    throw new FlightNotFoundError(flight);
  }
  const { airline, origin, destination } = body.response.flightroute;
  const [flightPrefix] = flight.split(" ", 1);
  return {
    airline: airline?.name ?? flightPrefix,
    airlineCode: airline?.iata ?? flightPrefix,
    from: placeOf(origin),
    to: placeOf(destination),
  };
}

import { getBoardingPass } from "@/features/flights/flight-queries";
import { FlightNotFoundError } from "@/features/flights/flight-route";
import {
  errorMessage,
  isFlightDate,
  normalizeFlightNumber,
} from "@/features/flights/flight-schema";

const CACHE = "private, max-age=300";

function today() {
  const now = new Date();
  return now.toISOString().slice(0, 10);
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const flight = normalizeFlightNumber(searchParams.get("flight") ?? "");
  const date = searchParams.get("date") ?? today();

  if (!flight || !isFlightDate(date)) {
    return Response.json(
      {
        error:
          'Pass a flight number such as "BA 117", and optionally a date as YYYY-MM-DD.',
      },
      { status: 400 }
    );
  }

  try {
    return Response.json(await getBoardingPass(flight, date), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    const status = error instanceof FlightNotFoundError ? 404 : 502;
    return Response.json(
      { error: errorMessage(error, "Flight lookup failed.") },
      { status }
    );
  }
}

